INSERT INTO game_system_changes VALUES(1,'FC26','engine','역할 커널은 결정적이지 않다 — EA가 역할 구속을 의도적으로 완화("less constrained by their Roles", 모든 역할 위치 조정)','EA Gameplay Deep Dive 원문 인용 (docs/20 ①)','적합도 Δ 0.02~0.05는 노이즈 구간 — 그 차이로 인선을 가르지 않는다(obs#91). 방법론의 구조적 상한','EA 피치노트','HIGH — 1차 자료','2026-08-11');
INSERT INTO game_system_changes VALUES(2,'FC26','roles','숙련도(Role+/++) 격차 축소 + Out of Position 페널티 대폭 감소','EA 원문 "bring them closer to Roles++" (docs/20 ②)','미숙련 회피에 큰 적합도를 지불하지 말 것. Δ≤.05면 숙련 우선, 크면 적합 우선(절충)','EA 피치노트','HIGH','2026-08-11');
INSERT INTO game_system_changes VALUES(3,'FC26','roles','역할·포커스 개명 — Wide Mid Balanced→Support 등 (FC25 표기와 동일 실체)','docs/20 ③ 대조표','문서 인용 시 표기 혼동 방지','EA/fut.gg','HIGH','2026-08-11');
INSERT INTO game_system_changes VALUES(4,'FC26','positioning','Wide Mid 리워크 — 수비 지향·백3 최적화("ideal for 3-back formations")','EA 원문 + 커널 자기진영 질량(Defend 1.30/Support 0.60) (docs/20 ④)','에메리 뱅크 칸=Support 기본. 알론소 3-4-2-1에는 최적, 백4 정합성은 미확인','EA 피치노트','HIGH','2026-08-11');
INSERT INTO game_system_changes VALUES(5,'FC26','attributes','AcceleRATE 3종 회귀(Explosive/Lengthy/Controlled) — 2차 속성은 힘(Strength)','전수 대조 20명, 힘 16/20 (obs#104, docs/20 ⑤)','sofifa 수집값 교차검증용. 효과 크기는 비공개라 적합 가중치로는 못 씀','EA+실측 대조','HIGH','2026-08-11');
INSERT INTO game_system_changes VALUES(6,'FC26','tactics','Team Press 수비 진영 너프(2026-05-28) — 진영별 비대칭 압박','EA TU 원문 (docs/20 ⑥)','고압박(이라올라)이 가장 불리, 에메리 미드블록 상대적 유리. 압박은 라인+수비접근으로 근사','EA 피치노트','HIGH','2026-08-11');
INSERT INTO game_system_changes VALUES(7,'FC26','meta','선수 행동 = OVR + HyperMotion + PlayStyles(온더볼) + Roles(오프더볼) — 커널은 Roles 층에만 대응','obs#87·#88·#90, 히트맵이 요구역할의 36.2%만 담음(obs#121)','실측 재현의 층위 한계를 명시 — 온더볼은 PlayStyles·스탯 레버','EA+실측','HIGH','2026-08-11');
INSERT INTO game_system_changes VALUES(8,'FC26','meta','미검증 잔여: 라인 높이 실효 / TU 1.1~1.3 원문 404 / Role++·OOP 정량','docs/20 ⑦','추정을 하드 제약으로 쓰지 않는다','—','기록','2026-08-11');
INSERT INTO game_system_changes VALUES(9,'FC26','positioning','윙 혼잡 회피 조정 — 와이드미드·풀백 공격 역할의 위치를 「측면 혼잡을 피하도록」 조정 + 윙백 전진은 「앞에 빈 공간이 있을 때」 발동','EA Gameplay Deep Dive: 「Tweaked Wide Mids and Fullbacks attacking Roles'' positions to avoid congestion in the wings」(FC IQ) · 「a Wingback can move forward if there is open space in front of them」(Positioning). 역할 정의: att_wb/Support=「rarely sprint back」(복귀 감소), att_wb/Attack=「push even higher」(전진 강화), insidefwd/Attack=「cutting inside」(측면 비움).','풀백 전진은 같은 쪽 와이드 역할이 결정한다 — 터치라인형(winger·widemid·wideplm) 뒤의 풀백은 올라가지 않으므로 wingback/Balanced로 두고, 전진시킬 풀백의 앞은 안쪽형 와이드로 비운다(C6와 결합: 윙어는 절제 사이드). 「풀백을 올리려고 양쪽 att_wb/Support」는 정의·메커니즘·C2 모두 위반. obs#443.','EA 피치노트 1차(2026-09-04 직독) · game_role_focus · obs#443','EA 문장 HIGH · 효과 크기 비공개 · 인게임 A/B 미실시','2026-09-04');
INSERT INTO game_system_changes VALUES(10,'FC27','roles','⭐ Attacking Spatial Awareness — 「Roles가 너무 엄격하게 느껴진다」는 진단에 EA가 내놓은 해법. AI 공격수가 주변 공간을 인식해 곡선 침투(Triggered Curved Runs)·Pass & Follow Runs로 움직인다. ⛔ 역할·포커스의 신설/삭제/개명은 어느 피치노트에도 없다(2026-09-04 기준 미공개).','FUT Deep Dive: 「Roles can sometimes feel too strict in gameplay, so in FC 27 we are introducing Attacking Spatial Awareness to help players recognise open space more naturally and make more decisive runs in attack.」 · Gameplay Deep Dive: 「makes AI attackers more aware of the space around them and how they move into it. … attackers would also run into crowded areas or struggle to find more effective space. In FC 27, they now make smarter, more contextual curved runs」 · 조작: 곡선 런 Tap L1+R1 / Pass&Follow L1+R1+X.','FC26 ①(「less constrained by their Roles」)의 연장·강화 — **역할 커널의 결정성이 한 단계 더 약해진다**. 우리 코사인 적합의 구조적 상한이 더 내려가므로 FC27 커널에서는 노이즈 구간(Δ≤0.05)을 넓게 볼 근거가 생긴다(크기는 실측 후 결정). ⚠️ 37/85/217 구조가 유지되는지는 fut.gg /api/fut/roles/ FC27 응답으로만 확정 — Kernel.EXPECTED 확장은 그때.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive (2026-07-29) · https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-fut-deep-dive','EA 1차 verbatim(HIGH) · 역할 목록 변화 여부는 미확인(UNKNOWN)','2026-09-04');
INSERT INTO game_system_changes VALUES(11,'FC27','engine','Triggered Runs 거리 제한 — 한 번의 트리거로 달리는 거리가 제한되고, 계속 달리게 하려면 다시 트리거해야 한다(클로즈드 베타 피드백 반영).','Beta Feedback Update: 「Triggered Runs will now have a limited distance. You''ll need to trigger another run if you want the player [to continue]」 — 「reduces some of the benefits Lengthy players could gain over extended distances」.','채널 러너형(st_advanced/Support·wm_winger/Attack)의 게임 내 침투 거리가 짧아진다 — 실측 「배후 침투」 서사를 게임에 옮길 때 한 번의 런으로 재현되지 않을 수 있음. 경기 프리셋 설명에 「런 재트리거 필요」 메모.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH) · 거리 수치 비공개','2026-09-04');
INSERT INTO game_system_changes VALUES(12,'FC27','attributes','AcceleRATE 영향 축소 — Explosive/Controlled/Lengthy 간 차이를 줄이고 가속력·질주속도 속성 비중을 높임. 여성 Lengthy 키 하한 172cm(5''8").','Beta Feedback Update: 「We''ve slightly reduced the impact of AcceleRATE profiles on a player''s running performance, bringing Explosive, Controlled, and Lengthy players a little closer together … greater emphasis on a player''s Acceleration and Sprint Speed Attributes」 · 「female players will need to be at least 5''8" (172 cm) to be eligible for Lengthy」.','docs/20 ⑤ 분류 공식(남 183cm 등)은 유지되나 **효과 크기가 줄어** 적합 가중치로 쓸 이유가 더 없어진다. 남성 임계값 변경 언급 없음 — 09-25 이후 sofifa/fut.gg accelerate 라벨 재대조 필요.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH) · 남성 임계값 불변 여부 미확인','2026-09-04');
INSERT INTO game_system_changes VALUES(13,'FC27','playstyles','PlayStyle 리밸런스 10종 + PlayStyle+ 상한 5→3(아이템당). Finesse Shot(속성 비중↑) · Technical(+와 격차↓) · Intercept(리치↑·소유 유지↑) · Rapid(드리블 속도 보너스↓) · Quick Step(가속 보너스↓) · Pinged Pass(수신자 트랩 오차 감소 효과 제거) · Tiki Taka(애니 속도 보너스·트랩 오차 감소 제거) · Jockey(비보유자 조키 가속↑·보너스↓) · Precision Header(정확도 보너스 재조정) · Low Driven(슛 속도 보너스 제거). Bruiser+ 추가 이득 소폭 축소.','Gameplay Deep Dive 각 항목 verbatim: 「We''ve updated Finesse Shot to make player attributes play a bigger role in shot outcome」 · 「Removed the effect that slightly reduced trap error on the pass receiver」(Pinged Pass) · 「Removed the animation playback speed boost and the effect that slightly reduced trap error」(Tiki Taka) · 「Removed the shot speed boost previously applied to low-driven shots」 · FUT Deep Dive: 「reducing the maximum number of PlayStyle+ available on a single Item from five to three」 · Beta: 「slightly reduced the additional benefit provided by Bruiser+」. 신설·삭제 PlayStyle 언급 없음.','docs/22 §3 카탈로그(35종)는 이름은 유지되되 **효과 서술 10건을 FC27 절로 갱신**해야 한다(특히 Pinged Pass·Tiki Taka의 「받기 쉬워짐」 문구는 FC27에서 거짓). player_game_stats.playstyles 해석 시 버전 주의. 온볼 층이라 커널 무관.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive (2026-07-29) · https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-fut-deep-dive · https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH) · 09-10 전체 DB 공개 시 신설/삭제 재확인','2026-09-04');
INSERT INTO game_system_changes VALUES(14,'FC27','tactics','Team Press — 자기 수비 3분의 1에서는 효과 없음(FC26 ⑥ 「수비 진영 너프」의 완성형). 낮은 수비 깊이 설정이 라인 위치에 더 뚜렷하게 반영.','Beta Feedback Update: 「Team Press will now have no effect while the ball is in your defensive third」 · 「defenders can still step towards their marked players, but will be less effective at applying pressure」 · 「lower depth settings are more clearly reflected in how your defensive line positions itself」.','FC26 ⑥의 진영별 비대칭이 **수비 3분의 1 완전 무효**로 굳어진다 — 이라올라(고압박) 재현 손실이 더 커지고, 에메리 딥블록 국면(PPDA 30 계열)은 게임에서 「팀 프레스 없음 + 낮은 깊이」로 오히려 정확히 재현된다. 라인 높이 실효(FC26 ⑦ 미검증)는 FC27에서 「더 뚜렷」해진다는 EA 진술 — 재검증 우선순위 상향.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH) · 수치 비공개','2026-09-04');
INSERT INTO game_system_changes VALUES(15,'FC27','engine','수동 수비 강화(Competitive 전용) — AI 수비수 인터셉트 리치 축소, 수동 조작 수비수 조키 속도↑·스탠딩 태클 범위↑. AI 수비수는 「포지셔닝 지원 역할」로.','Gameplay Deep Dive: 「we''re reducing the influence of AI-controlled defenders, putting more power into the hands of the manual defender」 · 「We''ve also reduced AI defensive reach for interceptions」 · 「manually-controlled defenders have increased jockey speed」 · 「increased the range of manually-triggered stand tackles」 · 「The following changes to AI Defending only apply to Competitive gameplay」.','수비 역할(cb_*/dm_holding)의 **AI 실행력이 낮아진다** — 커널(위치)은 그대로지만 「막아내는 결과」는 사용자 조작 의존. Intercept PlayStyle은 반대로 강화(#13) — AI 수비 재현은 PlayStyle 층으로 보상. Authentic(커리어)에는 미적용.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive (2026-07-29)','EA 1차 verbatim(HIGH)','2026-09-04');
INSERT INTO game_system_changes VALUES(16,'FC27','engine','Dinked Pass 완전 수동 — Ground Pass 입력으로는 불가(더블탭=일반 그라운드 패스), Through Pass 더블탭 + 수동 조준. Player Lock 시 볼 캐리어 자동 회피 제거·CPU 패스 오차↑.','Beta Feedback Update: 「Dinked Passes can no longer be performed using the Ground Pass input」 · 「double tap Through Pass and manually aim where you want the ball to go」 · 「the ball carrier will no longer automatically dribble around or avoid defenders」(Player Lock).','docs/22 §1 조작표 갱신 대상(FC27 절). 전술 재현과 무관한 조작 층.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH)','2026-09-04');
INSERT INTO game_system_changes VALUES(17,'FC27','meta','커리어 모드 — 선수당 최대 7포지션(주 1 + 부 6), 부 포지션에서는 OOP 페널티 없음, Dynamic OVR(폼·사기·경기체력), 포지션별 Baseline OVR 부활, 성장 프로필 6종, 슬라이더 25+10(CPU 상대/동료 분리). Authentic: CPU 전술 다양화·피지컬 접촉 강화·CPU 파울 증가.','Career Deep Dive: 「Players will now have up to seven positions they can perform in」 · 「Players performing in any of their six secondary preferred positions will not be penalised for playing outside their main position」 · 「dynamic determination of a player''s Baseline OVR based on the position they play in」 · 「Six distinct Growth Profiles」 · 「CPU-controlled players will also commit more fouls」.','**포지션 유연성이 게임 데이터 축으로 들어온다** — FC26 ②(OOP 페널티 대폭 감소)에서 한 발 더 나가 부 포지션은 무페널티. 우리 「측정 최적 ≠ EA 기본 포지션」 사례(맥긴 RM, 캐시 att_wb 등)의 게임 내 비용이 더 낮아진다. 커리어 축 데이터(7포지션 목록)는 09-10 DB에서 수집 대상 — player_game_stats.positions 해석 갱신.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-career-mode-deep-dive (2026-07-31)','EA 1차 verbatim(HIGH) · 숙련도 산식은 비공개','2026-09-04');
INSERT INTO game_system_changes VALUES(18,'FC27','meta','출시 초기 밸런스 정책 — 「초기 타이틀 업데이트에서 큰 게임플레이 밸런스 변경을 하지 않는다」. 발매 09-25(얼리액세스 09-18). ⛔ 역할 목록·팀 전술 파라미터 변화는 어느 피치노트에도 없음.','Beta Feedback Update: 「we do not plan on making significant gameplay balance changes in our early Title Updates」 · 「we don''t want to react quickly to early trends with significant balance changes」.','FC27 커널·파라미터 수집을 **발매 직후 1회로 잡아도 초기 TU로 흔들릴 위험이 작다**(FC26은 TU 1.4/1.5가 역할 위치를 바꿨다 — docs/20 ①). 역할 목록 미공개 상태이므로 09-18 얼리액세스 시점의 fut.gg /api/fut/roles/ 응답이 마이그레이션 트리거.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH)','2026-09-04');
